import {ToolRegistry} from './registry.js';

describe('ToolRegistry rejection logging contract', () => {
  it('reports rejected type and enum constraints without exposing values (spec: specs/hal-engine-tool-input-validation/spec.md#2)', async () => {
    const records: unknown[] = [];
    const record = (category: string, message: string, fields?: Record<string, unknown>) => {
      records.push({category, message, fields});
    };
    setLogger({debug: record, info: record, warn: record, error: record});
    try {
      const registry = new ToolRegistry();
      const executed: Record<string, unknown>[] = [];
      registry.register(
        {
          name: 'weather', description: 'Weather',
          inputSchema: {type: 'object', properties: {
            location: {type: 'number'}, units: {enum: ['metric', 'imperial']},
          }},
        },
        async input => { executed.push(input); return 'sunny'; }
      );
      const typeResponse = await registry.execute('weather', {location: 'private@example.com'});
      const enumResponse = await registry.execute('weather', {units: 'private@example.com'});
      expect({typeResponse, enumResponse, records, executed, leaked: JSON.stringify({typeResponse, enumResponse, records}).includes('private@example.com')}).toEqual({
        typeResponse: {result: expect.stringMatching(/location.*type.*number/)},
        enumResponse: {result: expect.stringMatching(/units.*enum/)},
        records: [
          {category: 'tool', message: 'input rejected', fields: {name: 'weather', result: expect.stringMatching(/location.*type.*number/)}},
          {category: 'tool', message: 'input rejected', fields: {name: 'weather', result: expect.stringMatching(/units.*enum/)}},
        ],
        executed: [], leaked: false,
      });
    } finally {
      setLogger();
    }
  });
});
''')
